pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let p = step_index as f64 / total_items as f64;                 // stream progress 0..1
    let cap_f = bin_capacity as f64;                                // capacity as f64
    let r = post_residual as f64 / cap_f;                           // residual fraction
    let mean_r = mean_residual / cap_f;                             // mean residual fraction

    let mut score = post_residual as f64;                            // base score = residual space

    if bin_residual == bin_capacity {
        // candidate for a brand‑new empty bin
        // encourage opening a new bin early in the stream, discourage late
        score -= 15.0 * (1.0 - p);
        // penalize opening new bins when many are already open
        score += 10.0 * open_bins_count as f64 * p;
    } else {
        // fitting into an existing bin
        // reward a large residual early (to avoid dead space) and
        // penalize too small residual later
        score += 80.0 * (1.0 - r).powi(3);

        // look‑ahead: prefer bins that leave space similar to the next item
        if next_item_size > 0 {
            let diff = (next_item_size as f64 - item_size as f64).abs();
            score -= 4.0 * (1.0 - diff / cap_f).powi(2);
        }

        // encourage bins whose residual is close to the current mean
        score += 8.0 * (mean_r - r).powi(2);

        // if this is the sole bin that can fit the item, slightly penalise
        // to favour opening a new bin that may fit future items better
        if fitting_bins_count == 1 {
            score += 25.0 * (1.0 - r);
        }
    }

    score
}

