pub fn score_bin(
    item_size: u32,
    _bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalized progress through the stream
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post‑residual space
    let mut score = post_residual as f64;

    // 1️⃣ Non‑linear penalty for small residuals that grows as we near the end
    score -= (post_residual as f64).powi(2) * progress;

    // 2️⃣ Reward bins that have many other fitting options early in the stream
    score += (fitting_bins_count as f64).powi(2) * (1.0 - progress);

    // 3️⃣ Penalise a mismatch between the residual of this bin and the overall mean
    //    more strongly when many bins are open and we are mid‑stream.
    score += (open_bins_count as f64) * (mean_residual - post_residual as f64).abs() * progress;

    // 4️⃣ Look‑ahead penalty: if the next item is big relative to what would remain,
    //    discourage using a bin that would leave very little space.
    if next_item_size > 0 {
        score += (next_item_size as f64) / (post_residual as f64 + 1.0) * (1.0 - progress);
    }

    // 5️⃣ Small bias: prefer placing smaller items earlier (lower score)
    score -= (item_size as f64) / (bin_capacity as f64) * progress;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual after placing the item.
    let mut score = post_residual as f64;

    // Handle the special case of a brand‑new bin.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin for relatively small items.
        if item_size < 70 {
            score += 20.0;
        }
        // Reward if the next item will also fit in this new bin.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    } else {
        // Existing bin – try to keep the best fit.
        if fitting_bins_count == 1 {
            score -= 10.0; // sole fitting bin is preferred
        }

        // Encourage residuals close to the mean residual across open bins.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score -= residual_diff * 0.1;

        // Lookahead: consider whether the next item can fit in this bin.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 3.0; // next item fits – good
            } else {
                score += 2.0; // next item won't fit – slight penalty
            }
        }

        // In the early part of the stream, penalize leaving large residuals.
        let step_ratio = step_index as f64 / total_items as f64;
        let early_penalty = (1.0 - step_ratio) * 5.0;
        score -= early_penalty;

        // If many bins are open, penalize keeping them open.
        if open_bins_count > 3 {
            score += (open_bins_count as f64 - 3.0) * 1.0;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score starts with the residual after placement
    let mut score = post_residual as f64;

    // 1. Aggressive 2‑step lookahead: compare post_residual with next_item_size
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Good fit for the next item – reward by reducing the score
            score -= diff as f64 * 0.5;
        } else {
            // Not enough space for the next item – penalise heavily
            score += (-diff as f64) * 2.0;
        }
    }

    // 2. Reward closeness of the resulting residual to the mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= dev * 0.3;

    // 3. Reward minimal waste before placing the item
    let waste_before = bin_residual as i32 - item_size as i32;
    if waste_before >= 0 {
        score -= waste_before as f64 * 0.2;
    }

    // 4. Extra penalty if this is the only fitting bin and the next item will not fit
    if fitting_bins_count == 1 && next_item_size > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // 5. Slight penalty for having many open bins – encourages tighter packing
    if open_bins_count > 1 {
        score += (open_bins_count as f64) * 0.1;
    }

    // 6. Near the end of the stream, slightly favour opening new bins to avoid dead space
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement
    let mut score = post_residual as f64;

    // Fill‑factor benefit: prefer bins that become more full
    let fill_factor = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_factor * 20.0;

    // Penalty if the next item would not fit in this bin
    if next_item_size > post_residual {
        let diff = (next_item_size - post_residual) as f64;
        score += diff * 2.0;
    }

    // Favor bins whose current residual is above the global mean
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Penalize creating too many open bins
    score += open_bins_count as f64 * 0.3;

    // Scale the score by the progress in the stream (early steps tolerate more waste)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };
    score *= 1.0 + (1.0 - progress) * 0.1;

    // If this is the only bin that can fit the item, strongly reward it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New‑bin handling: discourage opening a new bin unless justified
    if bin_residual == bin_capacity {
        // The bin is empty; decide based on how suitable it is for the next item
        if next_item_size > mean_residual as u32 {
            score -= 10.0; // reward opening a fresh bin when the next item is large
        } else {
            score += 15.0; // penalize opening a new bin for small items
        }
    }

    score
}
